def bits(v, w):
    return format(v & ((1 << w) - 1), "0" + str(w) + "b")


def arr(name, typ, vals, w):
    rows = []
    for i in range(0, len(vals), 8):
        rows.append("        " + ", ".join('"' + bits(v, w) + '"' for v in vals[i:i + 8]))
    return "    constant " + name + " : " + typ + " := (\n" + ",\n".join(rows) + "\n    );"


def emit():
    pc = [0] * 256
    for i in range(69):
        pc[i] = (CK[i] & 0xFF) << 10 | (DK[i] & 0x3FF)
    for i in range(128):
        pc[128 + i] = ((DU[i] << 29) | (ZN[i] << 27) | (A[i] << 22) | ((BO[i] & 0x7F) << 15) | ((C[i] & 0x3F) << 9)
                       | ((D0[i] & 0x1F) << 4) | M8[i])
    cr = []
    for s in range(256):
        w = CR_kill[s]
        w = (w << 4) | CR_ws[s]
        w = (w << 8) | CR_sw[s]
        w = (w << 8) | CR_knee[s]
        w = (w << 8) | CR_rg[s]
        w = (w << 8) | CR_br[s]
        w = (w << 8) | CR_r0[s]
        w = (w << 6) | CR_dr[s]
        w = (w << 8) | CR_mg[s]
        cr.append(w << 1)
    cs = [arr("C_T", "t_t", T8, 8), arr("C_PC", "t_pc", pc, 32), arr("C_ASIN", "t_ang", ASIN, 10),
          arr("C_SIN", "t_ang", SIN, 10), arr("C_CR", "t_cr", cr, 64), arr("C_E2", "t_e2", E2, 5)]
    txt = ("-- vase_pkg.vhd -- GENERATED by vase.py; edit the generator, not this file.\n\n"
           "library ieee;\nuse ieee.std_logic_1164.all;\n\npackage vase_pkg is\n"
           "    type t_t is array(0 to 4095) of std_logic_vector(7 downto 0);\n"
           "    type t_pc is array(0 to 255) of std_logic_vector(31 downto 0);\n"
           "    type t_ang is array(0 to 511) of std_logic_vector(9 downto 0);\n"
           "    type t_cr is array(0 to 255) of std_logic_vector(63 downto 0);\n"
           "    type t_e2 is array(0 to 63) of std_logic_vector(4 downto 0);\n"
           + "\n".join(cs) + "\nend package vase_pkg;\n")
    with open(os.path.join(HERE, "vase_pkg.vhd"), "w") as fh:
        fh.write(txt)


if __name__ == "__main__":
    emit()
